class Base:
 @classmethod
 def __class_getitem__(cls,key):return cls.__name__,key
class Child(Base):pass
print(Base[1],Child[2],Child.__class_getitem__(3))

class A:
 @staticmethod
 def __class_getitem__(key):return key+1
print(A[3],A.__class_getitem__(4))

class Base:
 def __class_getitem__(cls,key):return cls.__name__,key
class Child(Base):
 def __class_getitem__(cls,key):return super().__class_getitem__(key+1),__class__ is Child
print(Child[3])

events=[]
class Slot:
 def __get__(self,obj,owner):
  events.append((obj is None,owner.__name__))
  return lambda key:(owner.__name__,key)
class Base:__class_getitem__=Slot()
class Child(Base):pass
print(Child[3],events)

