class Base:
 def __class_getitem__(cls,key):return key
class Block(Base):__class_getitem__=None
class Bad:__class_getitem__=7
for cls in [Block,Bad]:
 try:cls[3]
 except TypeError as e:print(str(e))

class Key:
 def __index__(self):raise AssertionError('converted')
key=Key()
class A:
 def __class_getitem__(cls,value):return value
s=A[key:key:key]
print(type(s) is slice,s.start is key,s.stop is key,s.step is key)
t=A[1:3,4,*[5,6]]
print(t[0].start,t[0].stop,t[0].step,t[1:])
print(A[()],A[1,],A[...])

