 def __class_getitem__(cls,key):events.append(('old',key));return 1
def target():events.append('target');return A
def key():events.append('key');return 3
def rhs():events.append('rhs');return 2
try:target()[key()]+=rhs()
except TypeError:print(events)

events=[]
class Slot:
 def __get__(self,obj,owner):
  events.append('get')
  owner.__class_getitem__=lambda key:'new'
  return lambda key:'old'
class A:__class_getitem__=Slot()
print(A[3],A[4],events)

